 \item (cyclic symmetry) If $(a,b,c)\in\lambda$, then $(b,c,a)\in\lambda$. 

 \item (2-cycle axiom) If $(a,b,c)\in\lambda$, then $(a, a, c)\in\lambda$.

\end{enumerate}
A {\em total cyclic order} is a partial cyclic order satisfying the additional condition:
\begin{enumerate}[resume,label=(C\arabic{*})]
\item (comparability) For any $a,b,c$ we have either $(a,b,c)\in\lambda$, or $(b,a,c)\in\lambda$. 
\end{enumerate}

A {\em $\GG$-structured marked surface} is a datum consisting of:
	 \begin{enumerate}
	 \item[(1)] A compact surface $S$ (possibly with boundary). We denote $S^\circ= S-\partial S$ the interior of $S$.

	 \item[(2)] A finite subset $M\subset S$.

	 \item[(3)] A $\GG$-structure $F$ on $S-(M\cap S^\circ)$. 
	 \end{enumerate}

A marked surface $(S,M)$ is called {\em stable}, if:
\begin{enumerate}
\item[(1)]  $M\neq\emptyset$ and moreover, $M$ meets each component of $\partial S$.

\item[(2)] $\chi (S^\# - M^\#) < 0$. 
\end{enumerate}

define
\begin{equation}
	\label{eq:top-moduli}
	\Mc^\GG(S,M) = \Diff(S,M)\Bbs \Gstr(S-(M\cap S^\circ)) \simeq
	\Mod(S,M) \Bbs \Gstr(S-(M\cap S^\circ)) 
\end{equation}
as the ``topological" analog of the moduli space, in which we consider $\GG$ instead of $G_\conf$ as
a structure group.

\label{exa:embedding} Let $S$ be a surface. By an {\em embedding}
	of a graph  $\Gamma$ into $S$ we mean an injective, continous map $\gamma: |\Gamma| \to S$ such
	that
	\begin{itemize}
		\item $\gamma(|\Gamma|^\circ)$ is contained in the interior of $S$, and $\gamma(\partial|\Gamma|)\subset\partial S$.
		\item $\gamma$ is smooth along every edge of $|\Gamma|$.
		\item For every vertex $x$ of $|\Gamma|$ (corresponding to a vertex or
			and edge of $\Gamma$), the tangent directions of the edge germs on
		$S$ which leave $\gamma(x)$, are distinct.
	\end{itemize}

An {\em augmented $\DG$-structured graph} is a possibly noncompact $\DG$-structured graph $\Gamma$ equipped with
\begin{itemize}
	\item for every external halfedge $e \in H(v)$, an {\em augmentation map} $\varphi_e: H(v)
		\to [1]$ of $\DG$-structured sets, satisfying $\varphi_e^{-1}(\varphi(e)) = \{e\}$,
\end{itemize}
such that every vertex of $\Gamma$ has valency $\ge 2$.

