\begin{enumerate}
\item[(a)] A $\Lambda_\infty$-Frobenius algebra is the same as a finite-dimensional unital
	associative algebra $A$ together with a linear functional $\beta_1: A\to\k$ such that:
\begin{enumerate}
\item[(a1)] $\beta_2(a,b)=\beta_1(ab)$ is a non-degenerate, not necessarily symmetric bilinear form
	on $A$.

\item[(a2)] The Nakayama automorphism $F$ of $\beta_2$ is an algebra automorphism of $A$. 
\end{enumerate}

\item[(b)] A $\Lambda_N$-Frobenius algebra is a $\Lambda_\infty$-Frobenius algebra such that $F^N=\Id$. 
\end{enumerate}
\qed

\label{prop:morphisms-Gc}
The set $\Hom_\Gc((I', \Oc(I')), (I, \Oc(I)))$ is in bijection with the set of pairs
$(\psi_*, \psi^*)$, where $\psi_*: I'\to I$ and $\psi^*: \Oc(I)\to\Oc(I')$ are maps of sets such that:
\begin{itemize}
\item[(i)] For every structured frame $f$ of $I$, the unique map $f^*\psi: \{0,1,\dots, n'\}\to \{0,1,\dots, n\}$ making the
diagram
\[
\xymatrix{
\{0,1,\dots,n'\} 
\ar[d]_{\rho(\psi^*f)}\ar[r]^{f^*\psi }& \{0,1,\dots,n\} 
\ar[d]^{\rho(f)}
\\
I'\ar[r]_{\psi_*}&I
}
\]
commutative is given by a morphism in $\Delta$. 

\item[(ii)] For each frame $f$ of $I$ and $g\in\Gen_n$, we have
\[
\psi^*(f .  g) = \psi^*(f) . (f^*\psi)^*(g), 
\]
where $(f^*\psi)^*: \Gen_n\to\Gen_{n'}$ is the map associated to $f^*\psi$ via the simplicial set
$\Gen$. 
\end{itemize}

\label{prop:group-K}
\begin{enumerate}
\item[(a)] Let $\DG$ be the crossed simplicial group corresponding to $\GG$. Then $K=\Ker\{\rho: \Gen_0\to \ZZ/2\}$.

\item[(b)] The kernels corresponding to the various planar groups are given by:\\

  \begin{tabular}{ p{1cm} || p{2cm}| p{2cm}| p{2cm}|p{2cm}|p{2cm}}
	  $G$& $\on{Spin}_N(2)$& $\widetilde{SO(2)}$  & $\on{Pin}^+_N(2)$ & $\widetilde {O(2)}$& $\on{Pin}^-_{2M}(2)$
 \\
 \hline
 $K$ & $\ZZ/N$ & $\ZZ$ & $\ZZ/N$ & $\ZZ$ & $\ZZ/2M$
    \end{tabular}\\
 	If $G$ does not preserve orientation then $\tau$ acts on $K$ by $\tau(k)=-k$. 
\end{enumerate}

\label{prop:G-structures}
\begin{enumerate}
\item[(a)] Suppose $\GG$ preserves orientation, and let $S$ be an oriented surface. Then:
\begin{enumerate}
\item[(a1)] For any object $F\in\Gstr^+(S)$, the group $\Aut(F)$ is identified with $K$.

\item[(a2)] The set of isomorphism classes of objects of $\Gstr^+(S)$ is either empty or a torsor
over $H^1(S,K)$.
\end{enumerate}

\item[(b)] Suppose $\GG$ does not preserve orientation, and let  $S$
be any surface. Then: 

\begin{enumerate}
\item[(b1)] For  any object $F\in\Gstr(S)$, the group $\Aut(F)$ is identified with $H^0(S, \underline K^\orr)$. 

\item[(b2)] The set of isomorphism classes of objects of $\Gstr(S)$ is either empty, or is a torsor
over $H^1(S,\underline K^\orr)$.

\item[(b3)] The group  $H^0(S, \underline K^\orr)$ is identified with $K$, if $S$ is orientable, and with
the 2-torsion subgroup $K_2\subset K$, if $S$ is non-orientable. 
\end{enumerate}
\end{enumerate}

\label{prop:diff-contract}
If $(S,M)$ is a stable $\GG$-structured marked surface, then each component of
$\Diff^\GG(S,M)$ is contractible.

\label{prop:prod-of-grpds}
\begin{enumerate}
\item[(a)] For any surface $S$ we have a natural identification of groupoids
\[
\Gcstr(S) \simeq \Gstr(S)  \times  O(2)_\conf \on{Str}(S). 
\]
\item[(b)] The automorphism group of any object of $O(2)_\conf \on{Str}(S)$ is trivial.
\end{enumerate}

\label{prop:emb-graph-str}
	Let $S$ be a surface with a $\GG$-structure. An embedding of a graph $\Gamma$ into $S$ endows $\Gamma$
	with a $\DG$-structure.

\label{prop:tess-graph}
 $\TT(S,M)$ is homotopy equivalent to the nerve of the category $P(S,M)$. 
 \qed

\label{prop:nerve-classical}
 \begin{enumerate}
 \item[(a)] Assume that any finite intersection $U_{v_0}\cap\cdots\cap U_{v_p}$ is either
 empty or contractible. Then $|\N\Uc|$ is homotopy equivalent to $X$.

 \item[(b)] If, moreover, $\Uc$ is saturated, then $|\N^\leq \Uc|$ is homotopy
 equivalent to $X$. \qed


 \end{enumerate}

\label{prop:tess-A}
  The tessellation complex $\TT(S,M)$ is homeomorphic to $|(A, A_\infty)^\vee|$ so that each
  cell $\TT(\Pc)$ is identified with $A_\Pc$, the link of $\Pc$.

