\begin{thm}\label{thm:klein-teich}
\begin{enumerate}
\item[(a)] If $S$ is classical (i.e., orientable without boundary), then the space $\Teich(S,M)$ is the disjoint union of
two connected components, corresponding to the two orientations of $S$. Each component is canonically
identified with the corresponding classical Teichm\"uller space $\Teich^+(S,M)$. 

\item[(b1)] Suppose $S$ is non-classical, let $\pi: S^\#\to S$ be its Schottky double with involution
$\sigma$, and let $M^\#=\pi^{-1}(M)$. Let $g^\#$ be the genus of $S^\#$. Then
\[
\Teich(S,M) =  (\Teich^+(S^\#, M^\#))^{\sigma_{\Teich}}
\]
is the fixed point locus of the anti-holomorphic involution $\sigma_{\Teich}$. 
In particular, it is a real analytic manifold of dimension $3g^\#-3+|M^\#|$. 

\item[(b2)] Suppose $S$ is non-orientable, let $\varpi: \widetilde S\to S$ be its
orientation cover with the orientation reversing deck involution $\tau$, and let $\widetilde M=\varpi^{-1}(M)$.
Then
\[
	\Teich(S,M) = (\Teich^+(\widetilde S, \widetilde M))^{\tau_{\Teich}}
\]
is the fixed point locus of the involution $\tau_{\Teich}$. 

\item[(c)] In the situation (b1), the manifold $\Teich(S,M)$ is diffeomorphic to Euclidean space.

\end{enumerate}
\end{thm}

\begin{proof} Parts (a), (b1-2) are obvious. Part (c) was proved by Natanzon \cite{natanzon}
for $\partial S = M=\emptyset$ and Sepp\"al\"a \cite{seppala} for $M=\emptyset$. The extension 
to the case $M\neq\emptyset$ is can be done by the same methods.
\end{proof}

