\begin{defi}
	Given a graph $\Gamma$, we define its {\em realization} $|\Gamma| = |\N(I(\Gamma)|$ to be
	the geometric realization of its incidence category. We denote by $\partial |\Gamma|\subset|\Gamma|$ 
	the set of 1-valent vertices and by $|\Gamma|^\circ$ the complement $|\Gamma| - \partial|\Gamma|$. 
\end{defi}

\begin{rem}\label{rem:midpoint}
 	Note that the realization $|\Gamma|$ comes equipped with two kinds
	of $0$-cells. On the one hand, we have a $0$-cell for each vertex $v$ of $\Gamma$, on the
	other hand, we have a $0$-cell $m(e)$ for each edge $e$ of $\Gamma$ which can be regarded as a
	chosen midpoint of the geometric edge which connects the two vertices of $\Gamma$ incident
	to $e$, see Figure \ref{fig:F1}. 
\end{rem}

\begin{defi} \label{defi:ggraph} Let $\Gamma$ be a graph and let $\G$ be a small category equipped with a functor $\G
	\to \Set$. A {\em $\G$-structure on $\Gamma$} is a lift 
	\[
	\xymatrix{
			& \G \ar[d] \\
			I(\Gamma) \ar[r]^{I_{\Gamma}} \ar[ur]^{\widetilde{I_{\Gamma}}} & \Set
	}
	\]
	of the incidence diagram of $\Gamma$ to $\G$. 
\end{defi}

We now fix a planar Lie group $\rho: G \to O(2)$, the corresponding crossed
simplicial group $\DG$, and the larger (but equivalent) category $\G$ of $\DG$-structured sets. 
Note that the interpretation of the objects of $\G$ as sets with
extra structure gives a forgetful functor $\G \to \Set$. In this context, we will slightly abuse
notation, and refer to $\G$-structured graphs as $\DG$-structured graphs.

\begin{exas}\label{defi:exggraphs}  
	\begin{enumerate}
		\item A graph with a $\Lambda$-structure is called a {\em ribbon graph}.
		Explicitly, a $\Lambda$-structure on a graph $\Gamma$ is the datum of a cyclic order
		on the $H(v)$ for each vertex $v\in V$. Each  set $\{h,h'\}$ of half-edges of any edge $e$
		has a trivial cyclic order, since it has cardinality 2. 
		Thus, our definition reduces to the usual one
		\cite{penner:book}. 

		\item A graph with a $\Xi$-structure is called a {\em M\"obius graph}.
		Explicitly, a $\Xi$-structure on a graph $\Gamma$  consists,
		first, of a dihedral order on each $H(v)$ and, second, of identification
		of the orientation torsors 
		\[
		O(H(v))\buildrel\sim\over \lla O(e)\buildrel\sim\over \lra O(H(v'))
		\]
		for each edge $e$ with vertices
		$v$ and $v'$ (the case $v=v'$ is allowed).
		 This structure  
		is equivalent to the (somewhat more cumbersome)  concept of a M\"obius graph defined
		 in terms of ``ribbon graphs with  $\ZZ/2$-grading
		on edges" as in \cite{braun, mulase-waldron, mulase-yu}.  

		\item A graph with a $\Lambda_{\infty}$-structure is called a {\em framed graph}.
		\item A graph with a $\Lambda_N$-structure is called an {\em $N$-spin graph}.
		Very recently, surfaces with 2-spin structure were studied, from a combinatorial point of
		view by Novak and Runkel \cite{novak-runkel}. They introduced a concept of
		a combinatorial spin structure on a triangulation $T$ of a surface $S$. Such a structure
		equips the dual graph of $T$ with a $\Lambda_2$-structure in our sense. 
	\end{enumerate}
\end{exas}

For a 2-dimensional $\RR$-vector space $V$, we denote by
\[
C(V) \,\,=\,\, (V-\{0\})/\RR^*_{>0}
\]
the circle of directions of $V$. In particular, for any surface $S$ and any $x\in S$ we have the circle
$C(T_xS)$ of tangent directions at $x$.


\begin{defi} \label{exa:embedding} Let $S$ be a surface. By an {\em embedding}
	of a graph  $\Gamma$ into $S$ we mean an injective, continous map $\gamma: |\Gamma| \to S$ such
	that
	\begin{itemize}
		\item $\gamma(|\Gamma|^\circ)$ is contained in the interior of $S$, and $\gamma(\partial|\Gamma|)\subset\partial S$.
		\item $\gamma$ is smooth along every edge of $|\Gamma|$.
		\item For every vertex $x$ of $|\Gamma|$ (corresponding to a vertex or
			and edge of $\Gamma$), the tangent directions of the edge germs on
		$S$ which leave $\gamma(x)$, are distinct.
	\end{itemize}
\end{defi}

\begin{prop}\label{prop:emb-graph-str}
	Let $S$ be a surface with a $\GG$-structure. An embedding of a graph $\Gamma$ into $S$ endows $\Gamma$
	with a $\DG$-structure. 
\end{prop}

\begin{proof} 
	Let $h$ be a half-edge of $\Gamma$ incident to the vertex $v$ and with corresponding edge
	$e=\{h,h'\}$. We denote by $\gamma(|h|)$ the corresponding path in $S$ which runs from
	$\gamma(v)$ to the midpoint $m(e)= \gamma(e)$.


	A $\GG$-structure on $S$ gives, via the homotopy equivalence $\GG\to\Homeo^G(S^1)$, a
	$\Homeo^G(S^1)$-structure on each circle $C(T_xS)$. Therefore, by Corollary
	\ref{cor:structured-circle-orders}, each finite subset of $C(T_xS)$ becomes, canonically, a
	$\DG$-structured set. In particular, for each vertex $v \in V$, we have a canonical
	embedding of sets $H(v)\hookrightarrow C(T_{\gamma(v)} S)$ given by association to a
	half-edge $h$ the direction given by the germ of the path $\gamma(|h|)$ leaving $v$.  By
	the above, this provides a canonical $\DG$-structure on the set $H(v)$.  Further, let $e$ be
	an edge of $\Gamma$ given by a pair of half-edges $h, h'$  as above. 
	The two tangent directions to $|\Gamma|$ at $\gamma(m(e))$ correspond to the two half-edges
	$h$ and $h'$ of $e$. As before, the embedding $|\Gamma|\to S$ gives a $\DG$-structure on the
	2-element set of these directions, i.e., on $\{h,h'\}$. This defines the values of the
	functor $\widetilde I_\Gamma: I(\Gamma)\to \Gc$ on objects.

