	Similarly, let $J_e=A'\sqcup B'\subset C_e$ where $A'$ is a small closed arc around the
	image of $h$ in $C_e$ (denoted $a'$) and $B'$ is a small closed arc around the image of $h'$
	in $C_e$ (denoted $b'$). Note that the orientation torsors of $C_v$ and $C_e$ are identified
	by parallel transport along $\gamma(|h|)$. We now consider the space $\Phi$ formed by all
	orientation preserving homeomorphisms
	\[
	\phi: (C_v, J_v) \lra (C_e, J_e)
	\quad \text{s.t. } \phi(A)\subset A', \, \phi(B)\subset B'.
	\]
	These requirements define $\phi$ uniquely up to an isotopy (i.e., $\Phi$ is connected).
	Further, by Proposition \ref{prop:homeo-contr}, $\Phi$ is contractible. Consider now the
	unramified covering
	\[
	\pi: \Homeo^G(C_v, C_e) \lra \Homeo(C_v, C_e).
	\]
	As $\Phi$ is contractible, $\pi^{-1}(\Phi)$ is a disjoint union of components homeomorphic
	to $\Phi$.  We now show that the $\GG$-structure on $S$ defines a canonical choice of a
	component $\widetilde\Phi\subset\pi^{-1}(\Phi)$. By Theorem \ref{thm:CG=DG},
	$\widetilde\Phi$ will define a structure morphism $H(v)\to \{e,e'\}$ in $\Gc$. 

	Choose a Riemannian metric on $S$ (a contractible choice). This reduces the structure group
	of $S$ from $\GG$ to $G$. Let $T: C_v\to C_e$ be the Riemannian parallel transport along
	$\gamma(|h|)$.  It lifts canonically to a morphism of $\Homeo^G(S^1)$-structured circles.
	Denote this structured morphism by $\widetilde T$.  Let $\Pi$ be the space of paths
	$(T_s)_{s\in[0,1]}$ in $\Homeo(C_v, C_e)$ starting at $T$ and ending somewhere in $\Phi$.
	Any path $(T_s)\in\Pi$ defines a lift $\widetilde\Phi$ by transporting $\widetilde T$ along
	this path. Clearly, this $\widetilde \Phi$ depends only on the image of $(T_s)$ in
	$\pi_0(\Pi)$.  Note that $\pi_0(\Pi)$ is a torsor over $\ZZ = \pi_1 \,\Homeo^+(C_v, C_e)$.
	Note that $T$ sends the midpoint $b\in B$ (i.e, the image of $h$ in $C_v$) into the midpoint
	$b'\in B'$ (i.e., the image of $h'$ in $C_e$). Therefore we have a distinguished component
	$\Pi_0$ of $\Pi$ containing paths $(T_s)$ such that $T_s(B)$ meets $B'$ for all $s$. The
	transport of $\widetilde T$ along any path from $\Pi_0$ gives the component
	$\widetilde\Phi$. This concludes the argument. 
\end{proof}



\begin{exas}
\begin{enumerate}
	\item Suppose $\DG=\Lambda$. If $\Gamma$ be embedded into an oriented surface $S$, then it is classical that $\Gamma$
		is canonically a ribbon graph. Explicitly, each $H(v)$ has a cyclic order from the embedding
		into the oriented circle $C(T_{\gamma(v)} S)$, while the set of half-edges of any edge
		has a unique cyclic order since it has cardinality $2$. 

	\item Suppose $\DG=\Xi$.
		 Let $\Gamma$ be embedded into an unoriented surface $S$. Then $\Gamma$
		naturally admits the structure of a M\"obius graph.  The set 		$H(v)$ of half-edges incident to $v$
		inherits a dihedral order from the embedding into the circle $C(T_{\gamma(v)} S)$.
		The set $\{h,h'\}$ of half-edges of an edge $e$ is made into a dihedral set by looking at
		the orientation cover $\varpi: \widetilde \to S$: we define the orientation torsor $O(\{h,h'\})$
		of this set to be the set of sections of $\pi$ over the image, under $\gamma$, of the interior of $|e|$. 
		 Finally, we have to provide a lift of 
		the incidence map $i: H(s(h)) \to \{h,h'\}$ to a morphism of dihedrally ordered
		sets. Note that, by the path lifting property of the orientation cover $\pi$, 
		the orientation torsors of $H(s(h))$ and $\{h,h'\}$ are canonically
		identified. For every choice of orientation, there is now a unique linear
		order on $i^{-1}(h')$ compatible with the corresponding cyclic order of
		$H(s(h))$. These two linear orders are opposite providing $i$ with the
		structure of a morphism in ${\Xi}$.

	\item  Let $\DG={\Lambda}_\infty$. 
		Assume that $\Gamma$ is embedded into a framed surface $S$. This means, in
		particular, that $S$ is oriented so that we have a principal $GL^+(2,\RR)$-bundle $\Fr^+_S$ of positive frames on $S$. 
		Further, we are given a principal $\widetilde{GL^+(2,\RR)}$-bundle $\widetilde\Fr^+_S$ covering $\Fr^+_S$. 
		Thus, each fiber of $\widetilde\Fr^+_S$ is a universal cover of the corresponding fiber of $\Fr^+_S$.
		Let
		\[
		B^+ \,\,=\,\, \biggl\{
		\begin{pmatrix}
		a&b\\0&c
		\end{pmatrix}\,\in GL^+(2,\RR)\bigl\| \,\, a,c >0\biggr\}. 
		\]
		Then $B^+\backslash GL^+(2,\RR)=S^1$ is the circle of directions of $\RR^2$. Therefore 
		$B^+\backslash \Fr^+_S=C(T_S)$ is the circle bundle of directions of $T_S$. Further, $B^+$, being
		contractible, lifts canonically to a subgroup $\widetilde B^+\subset\widetilde{GL^+(2,\RR)}$.
		The quotient $\widetilde B^+\backslash \widetilde{GL^+(2,\RR)}\simeq\RR$ is the universal covering of
		$S^1$. So each fiber $\widetilde C(T_xS)= \widetilde B^+\backslash \widetilde\Fr^+_{S,x}$ is an oriented
		real line, equipped with the projection $\pi_x: \widetilde C(T_xS)\to C(T_xS)$
		exhibiting it as a universal covering of $C(T_xS)$. Therefore, for each vertex $v\in\Gamma$
		the preimage of $H(v)\subset C(T_{\gamma(v)}S)$ is naturally a $\ZZ$-torsor, thus giving a paracyclic
		order on $H(v)$. Similarly for each edge $\{h,h'\}$. We leave remaining details to the reader. 

	\item  Assume that $\Gamma$ is embedded into a surface $S$ which has an $N$-spin
		structure. Then, similarly to (3) , we consider an $N$-fold covering 
		$\pi_x: \widetilde C_N(T_xS)\to C(T_xS)$ for each $x\in S$. Taking $\pi_{\gamma(v)}^{-1}(H(v))$,
		we make each $H(v)$ into an $N$-cyclic set, and similarly for each set $\{h,h'\}$. 
\end{enumerate}

\end{exas}
















\subsection {Structured graphs and mapping class groups of structured surfaces}

Let $\DG$ be a planar crossed simplicial group, $G$ its corresponding planar Lie group, $\GG$ its
thick variant, and let $\Gc$ denote the category of $\DG$-structured sets. 

\begin{defi} Let $\Gamma$, $\Gamma'$ be graphs. A {\em weak equivalence} between $\Gamma$
	and $\Gamma'$ is a functor $\varphi: I(\Gamma) \to I(\Gamma')$ of incidence
	categories such that
	\begin{enumerate}
		\item $\varphi$ induces a bijection of the sets of vertices of valency $1$,
		\item the induced map $|\varphi|: |I(\Gamma)| \to |I(\Gamma')|$ is homotopy
			equivalence.
	\end{enumerate}
\end{defi}

Given a weak equivalence $\varphi: \Gamma \to \Gamma'$ of graphs we obtain an induced natural
transformation $\varphi^* I_{\Gamma'} \to I_{\Gamma}$ of incidence diagrams as follows: Given an
object $x$ of $I(\Gamma)$ corresponding to a vertex of $\Gamma$, we may represent each halfedge $e$ 
incident to $\varphi(x)$ by a path $\alpha$ in $|I(\Gamma')|$ which starts at $\varphi(x)$ and 
parametrizes the edge corresponding to $e$. The germ of the pullback of $\alpha$ at $x$ determines a
unique halfedge at $x$. This construction canonically determines a map $I_{\Gamma'}(\varphi(x)) \to
I_{\Gamma}(x)$. By a similar construction, one obtains maps $I_{\Gamma'}(\varphi(y)) \to
I_{\Gamma}(y)$ for every object $y$ corresponding to an edge of $\Gamma$ which assemble to the
desired natural transformation.

\begin{defi}\label{def:weak-eq-str-graphs}
	Let $\Gamma$, $\Gamma'$ be $\DG$-structured graphs.
	A {\em weak equivalence} $\varphi: \Gamma \to \Gamma'$ of $\DG$-structured graphs is a weak
	equivalence of underlying graphs together with a lift of the pullback morphism 
	$\varphi^* I_{\Gamma'} \to I_{\Gamma}$ to a morphism of $\G$-diagrams $\varphi^*
	\widetilde{I_{\Gamma'}} \to \widetilde{I_{\Gamma}}$.
	We define $\DGgraph$ to be the category with objects given by (compact) $\DG$-structured
	graphs without vertices of valency $2$ and morphisms given by weak equivalences.
\end{defi}

Note that this definition is analogous to that of a morphism of ringed spaces. 
Sometimes we will refer to weak equivalences of structured graphs as {\em contractions}. 

\begin{thm}\label{thm:g-graph} 
	The topological realization $|N(\DGgraph)|$ is a classifying space of $\GG$-structured surfaces so
	that we have a homotopy equivalence
	\[
		|\DGgraph| \simeq \coprod_{(S,M)} B\, \Mod^\GG(S,M),
	\]
	where the coproduct is taken over all topological types of stable marked $\GG$-structured surfaces $(S,M)$.
\end{thm}

The proof will be given in \S \ref{sub sub:decom-str}. 

\begin{defi}
Let $(S,M)$ be a stable marked surface. A {\em spanning graph} for $(S,M)$
is a graph $\Gamma$ together with an embedding $\gamma: |\Gamma|\to S$ such that:
\begin{enumerate}
\item $\gamma$ is a homotopy equivalence.
\item The restriction of $\gamma$ defines a homotopy equivalence between $\partial |\Gamma|$
(a finite set of points) and $\partial S - M$ (a finite set of open intervals). 
\end{enumerate}
We define the category $P(S,M)$ whose objects are isotopy classes of spanning graphs for $(S,M)$ and
with a unique morphism $[\Gamma] \to [\Gamma']$ if $[\Gamma']$ is obtained from $[\Gamma]$
by collapsing a forest. Note that $P(S,M)$ is in fact a poset.
\end{defi}

\begin{thm}\label{thm:graph-contr}
   For any stable marked surface $(S,M)$ the poset $P(S,M)$ is contractible. 
\end{thm}

The proof will be given in \S \ref{subsub:harer}. 

Assume that $(S,M)$ carries a $\GG$-structure. We then have a functor 
\begin{equation}\label{eq:rho}
	\rho: P(S,M) \lra \DGgraph
\end{equation}
which chooses for a graph $(\Gamma,\gamma)$ in every isotopy class and associates to it the
$\G$-structure on $\Gamma$ induced from the embedding $\gamma$ (Proposition \ref
{prop:emb-graph-str}). 
Further, the structured mapping class group $\Mod^{\GG}(S,M)$ acts on $P(S,M)$ and we can form the
semidirect product
\[
	\Mod^{\GG}(S,M) \ltimes P(S,M)
\]
as defined in Definition \ref{defi:semidirect}. The proof of Theorem \ref{thm:g-graph} amounts to
the statement that the functor $\rho$ extends to an equivalence of categories
\[
	\widetilde{\rho}: \Mod^{\GG}(S,M) \ltimes P(S,M) \lra \DGgraph,
\]
see Theorem \ref{thm:decomp}.

The 1- and 2-Segal conditions
\label{subset:simplicial-cyclic}

Let $\Delta$ be the {\em simplex category} of finite nonempty linearly ordered sets of the form $[n] = \{0,1,\dots,n\}$ with
morphisms given by monotone maps. Given categories $I$ and $\Cb$, we introduce the notation
\begin{align*}
	\Cb^I & = \Fun(I, \Cb), & \Cb_I & = \Fun(I^{\op}, \Cb)
\end{align*}
for the categories of covariant and contravariant functors.
The objects of $\Cb_{\Delta}$ are called {\em simplicial objects} in $\Cb$. 
If $\Cb$ admits limits, then we can use the formalism of Kan extension, to enlarge the domain of
definition of a simplicial object from $\Delta$ to $\Set_{\Delta}$. More precisely, let 
\[
	\Upsilon: \Delta^{\op} \to (\Set_{\Delta})^{\op}
\]
be the opposite of the Yoneda embedding. Then there exists an adjunction
\[
	\Upsilon^*: \Cb_{\Set_\Delta} \longleftrightarrow \Cb_{\Delta} : \Upsilon_*
\]
where, for a simplicial set $K$ and a simplicial object $X$, we have the explicit formula
\[
	\Upsilon_* X (K) = \pro_{\{\Delta^n \to K\}}^{\Cb} X_n
\]
given by a limit in $\Cb$ over the category of simplices of $K$. We introduce the notation
$(K,X) := \Upsilon_* X (K)$ and refer to it as the {\em object of $K$-membranes in $X$}.
Assume further, that $\Cb$ is equipped with a combinatorial model structure. Then we can derive the
above adjunction to obtain
\[
	L\Upsilon^*: \Ho(\Cb_{\Set_\Delta}) \longleftrightarrow \Ho(\Cb_{\Delta}): R \Upsilon_*
\]
where, as above, we have an explicit formula 
\[
	R \Upsilon_* X(K) \cong \hopro_{\{\Delta^n \to K\}}^{\Cb} X_n
\]
in terms of a homotopy limit in $\Cb$. We call $(K,X)_R := R \Upsilon_* X(K)$ the {\em derived
object of $K$-membranes in $X$}.

